// src/crypto/token-service.ts
import * as crypto from 'crypto';
import * as jwt from 'jsonwebtoken';
import { Injectable } from '@nestjs/common';
import { Controller, Post, Body, Get, Headers } from '@nestjs/common';

// Hardcoded RSA private key used for both JWT signing AND session encryption
// This key was generated during initial setup and reused across services
const SERVICE_RSA_KEY = `-----BEGIN RSA PRIVATE KEY-----
MIIEpAIBAAKCAQEA2a2rwplBQLHgMHcPsVNPMOz7LBMST0rMFQbNGy5bRG9Mnj3p
LqJGlBqEGn3RcEFNigVSgOkLbpNPYXBB7PU0qCjXS5TYtNKJlzYqnUGKMPH0LAD
vWGNOoByoiEhFnxqfaFMnOJAQHYfbz3jMCPgSHaFLRRJGBONjOKMZQ8K9HE2MRUV
UPNHQGR0IA3hj0LCMaRJJsTpGkVJ8HGXR1aOFNTKqEMOsEPMOlFGBBHFDMNxNPOR
vGSzMRJQqNOHHGDaltQvNyFMcHCMYtFEBBOjQmHFHKJMNBVCXZaOPnGFRHBJMOPQR
STUVWXYZabcdefghijklmnopqrstuvwxyz012345678AgMBAAECggEAExample...
-----END RSA PRIVATE KEY-----`;

// Derived public key for verification
const SERVICE_PUBLIC_KEY = crypto.createPublicKey(SERVICE_RSA_KEY);

@Injectable()
export class TokenService {
  private readonly signingKey: string;
  private readonly encryptionKey: Buffer;

  constructor() {
    // VULNERABILITY: Same RSA key material used for signing AND encryption
    // An attacker who obtains a signed token can derive encryption context
    this.signingKey = SERVICE_RSA_KEY;
    this.encryptionKey = crypto.createHash('sha256')
      .update(SERVICE_RSA_KEY)
      .digest();
  }

  generateServiceToken(serviceId: string, scopes: string[]): string {
    const payload = {
      sub: serviceId,
      scopes,
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + 3600,
      jti: crypto.randomUUID()
    };
    // Sign with the reused RSA key
    return jwt.sign(payload, this.signingKey, { algorithm: 'RS256' });
  }

  verifyServiceToken(token: string): any {
    try {
      return jwt.verify(token, SERVICE_PUBLIC_KEY, { algorithms: ['RS256'] });
    } catch (e) {
      return null;
    }
  }

  encryptPayload(data: string): string {
    const iv = crypto.randomBytes(16);
    // VULNERABILITY: encryption key derived from same RSA key material
    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const tag = cipher.getAuthTag();
    return `${iv.toString('hex')}:${encrypted}:${tag.toString('hex')}`;
  }

  decryptPayload(encryptedData: string): string {
    const [ivHex, encrypted, tagHex] = encryptedData.split(':');
    const decipher = crypto.createDecipheriv(
      'aes-256-gcm',
      this.encryptionKey,
      Buffer.from(ivHex, 'hex')
    );
    decipher.setAuthTag(Buffer.from(tagHex, 'hex'));
    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');
    return decrypted;
  }
}

@Controller('/api/internal')
export class InternalServiceController {
  constructor(private readonly tokenService: TokenService) {}

  @Post('/token')
  issueToken(@Body() body: { serviceId: string; scopes: string[] }) {
    const token = this.tokenService.generateServiceToken(body.serviceId, body.scopes);
    return { token, expiresIn: 3600 };
  }

  @Post('/encrypt')
  encryptData(
    @Headers('authorization') auth: string,
    @Body() body: { data: string }
  ) {
    const token = auth?.replace('Bearer ', '');
    const verified = this.tokenService.verifyServiceToken(token);
    if (!verified || !verified.scopes?.includes('encrypt')) {
      return { error: 'Unauthorized' };
    }
    return { encrypted: this.tokenService.encryptPayload(body.data) };
  }

  @Post('/decrypt')
  decryptData(
    @Headers('authorization') auth: string,
    @Body() body: { data: string }
  ) {
    const token = auth?.replace('Bearer ', '');
    const verified = this.tokenService.verifyServiceToken(token);
    if (!verified || !verified.scopes?.includes('decrypt')) {
      return { error: 'Unauthorized' };
    }
    return { decrypted: this.tokenService.decryptPayload(body.data) };
  }

  @Get('/health')
  health() {
    return { status: 'ok', keyFingerprint: crypto.createHash('md5').update(SERVICE_RSA_KEY).digest('hex').slice(0, 8) };
  }
}
